const raw = $input.first().json || {};
const sanitize = (str) => String(str || '')
  .replace(/Bearer\s+[A-Za-z0-9._~+/=-]+/gi, 'Bearer [REDACTED]')
  .replace(/(x-auth-token|api-subscription-key|x-n8n-webhook-secret|authorization)\s*[:=]\s*[^\s,;"]+/gi, '$1=[REDACTED]')
  .slice(0, 800);

return [{
  json: {
    source: 'n8n',
    workflowName: raw.workflow?.name || 'Unknown n8n Workflow',
    executionId: String(raw.execution?.id || ''),
    nodeName: raw.execution?.lastNodeExecuted || 'Unknown Node',
    errorCode: String(raw.execution?.error?.name || 'N8N_WORKFLOW_ERROR'),
    message: sanitize(raw.execution?.error?.message || 'Unhandled workflow failure'),
    metadata: {
      workflowId: raw.workflow?.id || null,
      mode: raw.execution?.mode || null,
      failedAt: new Date().toISOString(),
    },
  },
}];
